// Get temperature (tempC) and relative humidity (rh) from the input message
const tempC = msg.payload.tempC;
const rh = msg.payload.rh;

// Check if inputs are valid numbers
if (typeof tempC !== 'number' || typeof rh !== 'number') {
    node.error("Invalid input: tempC and rh must be numbers.", msg);
    return null;
}

// Calculate saturation vapor pressure (es) in kPa using the Buck equation approximation
// es = 0.6108 * exp(17.27 * T / (T + 237.3))
const saturationVP = 0.6108 * Math.exp((17.27 * tempC) / (tempC + 237.3));

// Calculate actual vapor pressure (ea) in kPa
// ea = (RH / 100) * es
const actualVP = (rh / 100) * saturationVP;

// Calculate Vapor Pressure Deficit (VPD) in kPa
// VPD = es - ea = es * (100 - RH) / 100
const vpd = saturationVP - actualVP;

// Set the output message payload to the calculated VPD, rounded to 2 decimal places
msg.payload = parseFloat(vpd.toFixed(2));
//msg.payload = vpd.toFixed(2);

return msg;

